<span class="line"><span style="color:#C678DD;">        int</span><span style="color:#E06C75;"> k</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">;         </span><span style="color:#7F848E;font-style:italic;">// 临时数组的指针</span></span>
