<span class="line"><span style="color:#C678DD;">        while</span><span style="color:#ABB2BF;"> (</span><span style="color:#E06C75;">i</span><span style="color:#56B6C2;"> &lt;=</span><span style="color:#E06C75;"> mid</span><span style="color:#56B6C2;"> &amp;&amp;</span><span style="color:#E06C75;"> j</span><span style="color:#56B6C2;"> &lt;=</span><span style="color:#E06C75;"> right</span><span style="color:#ABB2BF;">)</span></span>
